Ext._define('common.clinical.prescription.Manage', {
    extend: 'toolkit.widget.TabPanel',

    _gridResizeEvent: function (grid, adjWidth) {
        grid.getKeywordField().setWidth(adjWidth - 350);
    },

    getPatientGrid: function (cfg) {
        if (!this._patientGrid) {
            this._patientGrid = Ext._create('common.clinical.naturalperson.Grid', {
                region: 'north',
                title: 'Pacientes',
                height: 300,
                split: true,
                gridAutoLoad: true,
                border: false,
                onlyColumns: [
                    'nome',
                    'cpf',
                    'sexo_display',
                    'data_nascimento',
                ],
            });

            this._patientGrid.getSelectionModel().on({
                scope: this,
                selectionchange: function(sm) {
                    var selection = sm.getSelections();

                    if (selection.length > 0)
                        this.patient(selection[0].data);
                    else
                        this.patient(null);
                }
            });

            this._patientGrid.on({
                scope: this,
                resize: this._gridResizeEvent,
            });
        }

        return this._patientGrid;
    },

    getPrescriptionGrid: function(cfg) {
        if (!this._prescriptionGrid) {
            this._prescriptionGrid = Ext._create('common.clinical.prescription.Grid', {
                region: 'center',
                title: 'Receituários',
                border: false,
                gridAutoLoad: false,
                onlyColumns: [
                    'cache_number',
                    'patient_unicode',
                    'signed_by_unicode',
                    'signed_at',
                ],
            });

            this._prescriptionGrid.getSelectionModel().on({
                scope: this,
                selectionchange: function(sm) {
                    var selection = sm.getSelections();

                    if (selection.length > 0)
                        this.prescription(selection[0].data);
                    else
                        this.prescription(null);
                }
            });

            this._prescriptionGrid.on({
                scope: this,
                resize: this._gridResizeEvent,
            });
        }

        return this._prescriptionGrid;
    },

    patient: function(value, dispatch) {
        dispatch = (dispatch === undefined ? true : dispatch);

        if(value !== undefined) {
            this._patient = value;

            if(dispatch)
                this.patientObserve();
        }

        return this._patient;
    },

    patientObserve: function() {
        var value = this.patient();

        if(value) {
            this.getPrescriptionGrid().enable();
            this.getPrescriptionGrid().setParam('patient', value.pk);
            this.getPrescriptionGrid().setFilterProperty('patient', value.pk, 1000);
        }
        else {
            this.getPrescriptionGrid().disable();
            this.getPrescriptionGrid().setParam('patient', 0);
            this.getPrescriptionGrid().setFilterProperty('patient', 0, 1000, false);
            this.getPrescriptionGrid().getStore().removeAll();
        }
    },

    prescription: function(value, dispatch) {
        dispatch = (dispatch === undefined ? true : dispatch);

        if(value !== undefined) {
            this._prescription = value;

            if(dispatch)
                this.prescriptionObserve();
        }

        return this._prescription;
    },

    prescriptionObserve: function() {
        var value = this.prescription();

        this.getTilePanel().setPageContent('');

        if(value) {
            this.getTilePanel().enable();
            this.renderContent(value.pk);
        }
        else {
            this.getTilePanel().disable();
        }
    },

    renderContent: function(prescriptionId) {
        var rest = Ext._create('common.clinical.prescription.Restful');
        var mask = new Ext.LoadMask(this.getTilePanel().getEl(), {msg: 'renderizando...'});

        mask.show();
        rest.renderContent(
            prescriptionId,
            {
                scope: this,
                fn: function(result) {
                    this.getTilePanel().setPageContent(result.content);
                }
            },
            {
                scope: this,
                fn: function(message) {
                    Ext.Msg.show({
                        title: 'Visualizando',
                        msg: message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });

                    this.getTilePanel().setPageContent(message);
                }
            },
            {
                fn: function() { mask.hide() }
            },
        );
    },

    getTilePanel: function (cfg) {
        if (!this._tilePanel) {
            this._tilePanel = Ext._create('core.TilePagePanel', {
                region: 'center',
            });
        }

        return this._tilePanel;
    },

    _resizeEvent: function (panel, adjWidth) {
        var newWidth = 0;

        var MANAGER_WIDTH = adjWidth;
        var TILE_WIDTH = 830;
        var LAPTOP_BASIC_WIDTH = 1366;

        if (MANAGER_WIDTH <= LAPTOP_BASIC_WIDTH) {
            newWidth = MANAGER_WIDTH * 45 / 100;  // Use 45% of the manager width
        } else {
            newWidth = MANAGER_WIDTH - TILE_WIDTH;
        }

        this.getGridContainer().setWidth(newWidth);
    },

    getGridContainer: function (cfg) {
        if (this._gridContainer) {
            return this._gridContainer;
        }

        this._gridContainer = Ext._create('Ext.Panel', {
            region: 'west',
            border: false,
            split: true,
            layout: 'border',
            items: [
                this.getPatientGrid(cfg),
                this.getPrescriptionGrid(cfg),
            ],
        });

        return this._gridContainer;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(cfg, {
            title: 'Gestor de Receituário Médico',
        });

        Ext.apply(cfg, {
            layout: 'border',
            items: [
                this.getGridContainer(cfg),
                this.getTilePanel(cfg),
            ],
            listeners: {
                scope: this,
                resize: this._resizeEvent,
            },
        });

        common
          .clinical
          .prescription
          .Manage
          .superclass
          .constructor
          .call(this, cfg);

        this.patientObserve();
        this.prescriptionObserve();
    }
});
